 1→/**
 2→ * Upload Throughput Scenario
 3→ *
 4→ * N clients each upload M files (1KB-500KB), measuring upload pipeline
 5→ * throughput including IPNS publish per file.
 6→ */
 7→
 8→import { describe, it, afterAll } from 'vitest';
 9→import {
10→  createClientPool,
11→  destroyClientPool,
12→  aggregateAndReport,
13→  type PoolClient,
14→} from '../harness/client-pool';
15→import { runFileWorkload } from '../workloads/file-workload';
16→
17→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '10', 10);
18→const FILES_PER_CLIENT = 20;
19→
20→describe('Upload Throughput', () => {
21→  let pool: PoolClient[] = [];
22→
23→  afterAll(async () => {
24→    await destroyClientPool(pool);
25→  });
26→
27→  it(`${NUM_CLIENTS} clients × ${FILES_PER_CLIENT} files (1KB-500KB)`, async () => {
28→    pool = await createClientPool({
29→      clientCount: NUM_CLIENTS,
30→      label: 'upload-throughput',
31→    });
32→
33→    const results = await Promise.allSettled(
34→      pool.map((pc) => {
35→        pc.metrics.start();
36→        return runFileWorkload(pc, {
37→          fileCount: FILES_PER_CLIENT,
38→          minSize: 1_024,
39→          maxSize: 500 * 1_024,
40→          verifyDownloads: false,
41→        }).finally(() => pc.metrics.stop());
42→      })
43→    );
44→
45→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
46→    const failed = results.filter((r) => r.status === 'rejected').length;
47→    console.log(`\nClients completed: ${succeeded} succeeded, ${failed} failed`);
48→
49→    await aggregateAndReport('Upload Throughput', pool);
50→  });
51→});
