  1→/**
  2→ * @cipherbox/sdk - CipherBoxClient
  3→ *
  4→ * Stateful client orchestrating folder CRUD, file upload/download,
  5→ * and event-driven change notification. Wraps @cipherbox/sdk-core
  6→ * stateless functions with internal state management (FolderTree, KeyCache).
  7→ *
  8→ * Design principles:
  9→ * - Zero React/Zustand/browser dependencies
 10→ * - All state flows through typed events (SdkEvent)
 11→ * - Operations are wrapped with withOperation() for consistent
 12→ *   start/end/error event emission
 13→ * - Key material is cleared on destroy()
 14→ */
 15→
 16→import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
 17→import * as sdkCore from '@cipherbox/sdk-core';
 18→import { createAxiosInstance } from '@cipherbox/api-client';
 19→import { clearBytes } from '@cipherbox/crypto';
 20→import type { FolderChild } from '@cipherbox/core';
 21→import type { CipherBoxClientConfig, FolderState } from './types';
 22→import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
 23→import { FolderTree } from './state/folder-tree';
 24→import { KeyCache } from './state/key-cache';
 25→import * as binOps from './bin';
 26→import type { BinState } from './bin';
 27→import * as shareOps from './share';
 28→import type { SentShareInfo } from './share';
 29→
 30→/** Thrown when a bin operation is attempted before loadBin() has been called. */
 31→export class BinNotLoadedError extends Error {
 32→  constructor() {
 33→    super('Bin not loaded');
 34→    this.name = 'BinNotLoadedError';
 35→  }
 36→}
 37→
 38→export class CipherBoxClient {
 39→  private config: CipherBoxClientConfig;
 40→  private ctx: SdkContext;
 41→  private emitter: SdkEventEmitter;
 42→  private folderTree: FolderTree;
 43→  private keyCache: KeyCache;
 44→  private binState: BinState | null = null;
 45→  /** Internal copies of key material — zeroed on destroy() without affecting caller buffers */
 46→  private internalVaultKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
 47→  private internalRootFolderKey: Uint8Array;
 48→
 49→  constructor(config: CipherBoxClientConfig) {
 50→    // Defensive copy of key material so destroy() only zeroes our copies
 51→    this.internalVaultKeypair = {
 52→      publicKey: new Uint8Array(config.vaultKeypair.publicKey),
 53→      privateKey: new Uint8Array(config.vaultKeypair.privateKey),
 54→    };
 55→    this.internalRootFolderKey = new Uint8Array(config.rootFolderKey);
 56→    this.config = {
 57→      ...config,
 58→      vaultKeypair: this.internalVaultKeypair,
 59→      rootFolderKey: this.internalRootFolderKey,
 60→    };
 61→    const axiosInstance =
 62→      config.axiosInstance ??
 63→      createAxiosInstance({
 64→        baseUrl: config.apiUrl,
 65→        getAccessToken: config.getAccessToken,
 66→        defaultHeaders: config.defaultHeaders,
 67→      });
 68→    this.ctx = {
 69→      apiUrl: config.apiUrl,
 70→      getAccessToken: config.getAccessToken,
 71→      axiosInstance,
 72→    };
 73→    this.emitter = new SdkEventEmitter();
 74→    this.folderTree = new FolderTree();
 75→    this.keyCache = new KeyCache();
 76→  }
 77→
 78→  // ---- Event subscription ----
 79→
 80→  /** Subscribe to SDK events. Returns an unsubscribe function. */
 81→  on(handler: SdkEventHandler): () => void {
 82→    return this.emitter.on(handler);
 83→  }
 84→
 85→  /** Unsubscribe a previously registered handler. */
 86→  off(handler: SdkEventHandler): void {
 87→    this.emitter.off(handler);
 88→  }
 89→
 90→  // ---- Lifecycle ----
 91→
 92→  // ---- Share re-wrapping (internal) ----
 93→
 94→  /**
 95→   * Re-wrap keys for share recipients after adding items to a folder.
 96→   *
 97→   * Queries the share callbacks for active shares covering the folder,
 98→   * then wraps each new item's plaintext key for each recipient.
 99→   * Failures are logged but do not propagate (re-wrapping is best-effort).
100→   */

