 1→/**
 2→ * SDK Context -- injected configuration for all sdk-core functions.
 3→ * Replaces the Zustand store access pattern (useAuthStore.getState()).
 4→ */
 5→export type SdkContext = {
 6→  /** Base URL for the CipherBox API (e.g., "http://localhost:3000") */
 7→  apiUrl: string;
 8→  /** Returns a valid access token. Consumer owns refresh logic. */
 9→  getAccessToken: () => Promise<string>;
10→  /**
11→   * Instance-scoped axios for API calls.
12→   * When provided, orval-generated functions use this instance instead of
13→   * the module-level singleton, enabling per-client token isolation.
14→   */
15→  axiosInstance?: import('axios').AxiosInstance;
16→};
17→
18→/**
19→ * TEE key configuration, passed explicitly instead of read from auth store.
20→ */
21→export type TeeKeys = {
22→  currentPublicKey: string;
23→  currentEpoch: number;
24→  previousPublicKey?: string | null;
25→  previousEpoch?: number | null;
26→};
27→
28→/**
29→ * Result of an IPFS upload operation.
30→ */
31→export type IpfsAddResult = {
32→  cid: string;
33→  size: number;
34→  recorded: boolean;
35→};
36→
37→/**
38→ * Progress callback for upload/download operations.
39→ */
40→export type ProgressCallback = (percent: number) => void;
41→export type DownloadProgressCallback = (loaded: number, total: number) => void;
