 81→/**
 82→ * Create a new subfolder with generated keys.
 83→ *
 84→ * Generates new Ed25519 IPNS keypair and AES-256 folder key,
 85→ * wraps them with the user's public key for storage.
 86→ *
 87→ * @returns Created folder entry and decrypted keys
 88→ */
 89→export async function createSubfolder(params: {
 90→  name: string;
 91→  userPublicKey: Uint8Array;
 92→  teeKeys?: TeeKeys;
 93→}): Promise<{
 94→  folder: FolderEntry;
 95→  ipnsPrivateKey: Uint8Array;
 96→  folderKey: Uint8Array;
 97→  encryptedIpnsPrivateKey?: string;
 98→  keyEpoch?: number;
 99→}> {
100→  // 1. Generate Ed25519 keypair for folder IPNS
101→  const ipnsKeypair = await generateEd25519Keypair();
102→  const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
103→
104→  // 2. Generate random AES-256 folder key
105→  const folderKey = generateRandomBytes(32);
106→
107→  // 3. Wrap keys with user's public key (ECIES encryption)
108→  const ipnsPrivateKeyEncrypted = bytesToHex(
109→    await wrapKey(ipnsKeypair.privateKey, params.userPublicKey)
110→  );
111→  const folderKeyEncrypted = bytesToHex(await wrapKey(folderKey, params.userPublicKey));
112→
113→  // 4. TEE-02: Encrypt IPNS private key with TEE public key for republishing.
114→  //    Wrap remaining steps in try/catch to zero key material on error.
115→  //    On success the caller receives the keys, so we only zero on failure.
116→  try {
117→    let encryptedIpnsPrivateKey: string | undefined;
118→    let keyEpoch: number | undefined;
119→
120→    if (params.teeKeys?.currentPublicKey) {
121→      const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
122→      const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
123→      encryptedIpnsPrivateKey = bytesToHex(encryptedKey);
124→      keyEpoch = params.teeKeys.currentEpoch;
125→    }
126→
127→    // 5. Create folder entry for parent's metadata
128→    const now = Date.now();
129→    const folder: FolderEntry = {
130→      type: 'folder',
131→      id: crypto.randomUUID(),
132→      name: params.name,
133→      ipnsName,
134→      ipnsPrivateKeyEncrypted,
135→      folderKeyEncrypted,
136→      createdAt: now,
137→      modifiedAt: now,
138→    };
139→
140→    return {
141→      folder,
142→      ipnsPrivateKey: ipnsKeypair.privateKey,
143→      folderKey,
144→      encryptedIpnsPrivateKey,
145→      keyEpoch,
146→    };
147→  } catch (error) {
148→    ipnsKeypair.privateKey.fill(0);
149→    folderKey.fill(0);
150→    throw error;
151→  }
152→}
153→
