  1→/**
  2→ * @cipherbox/sdk - Event system
  3→ *
  4→ * Typed event definitions and a simple emitter for SDK state changes.
  5→ * Consumers subscribe to events to sync external state (e.g., Zustand stores)
  6→ * with SDK-internal state changes.
  7→ *
  8→ * Design: No external dependencies. The emitter is synchronous and
  9→ * subscriber errors are caught to prevent cascading failures.
 10→ */
 11→
 12→import type { FolderChild } from '@cipherbox/core';
 13→import type { BinEntry } from '@cipherbox/core';
 14→
 15→/**
 16→ * Union of all events emitted by the SDK.
 17→ *
 18→ * Events follow the pattern `domain:action` for easy filtering
 19→ * by consumers who only care about specific domains.
 20→ */
 21→export type SdkEvent =
 22→  | {
 23→      type: 'folder:loaded';
 24→      folderId: string;
 25→      ipnsName: string;
 26→      children: FolderChild[];
 27→      sequenceNumber: bigint;
 28→    }
 29→  | {
 30→      type: 'folder:updated';
 31→      folderId: string;
 32→      ipnsName: string;
 33→      children: FolderChild[];
 34→      sequenceNumber: bigint;
 35→    }
 36→  | { type: 'folder:deleted'; folderId: string }
 37→  | { type: 'file:uploaded'; folderId: string; fileName: string; cid: string }
 38→  | { type: 'file:downloaded'; cid: string }
 39→  | { type: 'bin:updated'; entries: BinEntry[] }
 40→  | { type: 'share:reWrapFailed'; folderIpnsName: string; failedRecipients: string[] }
 41→  | { type: 'ipns:batchPublishFailed'; ipnsNames: string[]; error: Error }
 42→  | { type: 'operation:start'; operation: string }
 43→  | { type: 'operation:end'; operation: string; durationMs: number }
 44→  | { type: 'error'; operation: string; error: Error };
 45→
 46→/**
 47→ * Handler function for SDK events.
 48→ * Consumers implement this to react to state changes.
 49→ */
 50→export type SdkEventHandler = (event: SdkEvent) => void;
 51→
 52→/**
 53→ * Simple typed event emitter. No external dependencies.
 54→ *
 55→ * Consumers subscribe with on() and unsubscribe with off() or the
 56→ * returned unsubscribe function. Handler errors are caught silently
 57→ * to prevent one subscriber from crashing the SDK or other subscribers.
 58→ */
 59→export class SdkEventEmitter {
 60→  private handlers: SdkEventHandler[] = [];
 61→
 62→  /**
 63→   * Subscribe to all SDK events.
 64→   * @returns An unsubscribe function for convenience
 65→   */
 66→  on(handler: SdkEventHandler): () => void {
 67→    this.handlers.push(handler);
 68→    return () => this.off(handler);
 69→  }
 70→
 71→  /**
 72→   * Unsubscribe a previously registered handler.
 73→   */
 74→  off(handler: SdkEventHandler): void {
 75→    this.handlers = this.handlers.filter((h) => h !== handler);
 76→  }
 77→
 78→  /**
 79→   * Emit an event to all subscribers.
 80→   * Handler errors are caught and swallowed -- subscriber bugs
 81→   * must not crash the SDK.
 82→   */
 83→  emit(event: SdkEvent): void {
 84→    for (const handler of this.handlers) {
 85→      try {
 86→        handler(event);
 87→      } catch {
 88→        /* subscriber errors don't crash SDK */
 89→      }
 90→    }
 91→  }
 92→
 93→  /**
 94→   * Remove all handlers. Called during client destroy().
 95→   */
 96→  removeAll(): void {
 97→    this.handlers = [];
 98→  }
 99→}
